def skriv_till_fil(elever):
  """Sparar produkter och priser på fil
  Inparameter: elever, lista med elev-objekt)
  Returerar:  inget"""
  fil = open("elever.txt", "w")
  for objekt in elever:
    fil.write(objekt.namn + " ")
    for element in objekt.hopp:
      fil.write(str(element) + " ")
