  fil.close()

def hoppa_om(elev):
  val = input("Vill du låta " + elev.namn + " hoppa om? (J/N)")
  if val[0].upper() == "J":
    elev.hoppat(len(elev.hopp))
  else:
    print("Tillbaka till huvudmenyn")


